## protos/common/types.proto

```protobuf
syntax = "proto3";

package common;

option go_package = "github.com/iot_platform/common";

// Pagination
message PaginationRequest {
    int32 page = 1;
    int32 page_size = 2;
}

message PaginationResponse {
    int32 total = 1;
    int32 page = 2;
    int32 page_size = 3;
    int32 total_pages = 4;
}

// Common response wrapper
message Empty {}

message ErrorResponse {
    int32 code = 1;
    string message = 2;
    map<string, string> details = 3;
}

// Timestamps
message Timestamp {
    int64 seconds = 1;
    int32 nanos = 2;
}
```

## protos/device_service/service.proto

```protobuf
syntax = "proto3";

package device_service;

import "common/types.proto";

option go_package = "github.com/iot_platform/device_service";

// Device message
message Device {
    string id = 1;
    string name = 2;
    string email = 3;
    string status = 4;
    map<string, string> metadata = 5;
    common.Timestamp created_at = 6;
    common.Timestamp updated_at = 7;
}

// Request/Response messages
message CreateDeviceRequest {
    string name = 1;
    string email = 2;
    map<string, string> metadata = 3;
}

message CreateDeviceResponse {
    Device device = 1;
}

message GetDeviceRequest {
    string id = 1;
}

message GetDeviceResponse {
    Device device = 1;
}

message ListDevicesRequest {
    common.PaginationRequest pagination = 1;
    string status = 2;
    string search = 3;
}

message ListDevicesResponse {
    repeated Device devices = 1;
    common.PaginationResponse pagination = 2;
}

message UpdateDeviceRequest {
    string id = 1;
    optional string name = 2;
    optional string email = 3;
    optional string status = 4;
    map<string, string> metadata = 5;
}

message UpdateDeviceResponse {
    Device device = 1;
}

message DeleteDeviceRequest {
    string id = 1;
}

message DeleteDeviceResponse {
    bool success = 1;
}

// Streaming messages
message DeviceEvent {
    string event_type = 1;  // created, updated, deleted
    Device device = 2;
    common.Timestamp timestamp = 3;
}

// Service definition
service DeviceServiceService {
    // Unary RPCs
    rpc CreateDevice(CreateDeviceRequest) returns (CreateDeviceResponse);
    rpc GetDevice(GetDeviceRequest) returns (GetDeviceResponse);
    rpc UpdateDevice(UpdateDeviceRequest) returns (UpdateDeviceResponse);
    rpc DeleteDevice(DeleteDeviceRequest) returns (DeleteDeviceResponse);
    rpc ListDevices(ListDevicesRequest) returns (ListDevicesResponse);

    // Server streaming RPC
    rpc WatchDevices(common.Empty) returns (stream DeviceEvent);

    // Bidirectional streaming RPC
    rpc BulkDeviceOperations(stream CreateDeviceRequest) returns (stream CreateDeviceResponse);
}
```

## device-service/server.py

```python
import asyncio
import logging
from concurrent import futures
import grpc
from grpc_reflection.v1alpha import reflection
from grpc_health.v1 import health_pb2, health_pb2_grpc
from grpc_health.v1.health import HealthServicer
from opentelemetry import trace
from opentelemetry.instrumentation.grpc import GrpcInstrumentorServer
from prometheus_client import start_http_server, Counter, Histogram

from generated import device_service_pb2
from generated import device_service_pb2_grpc
from service import DeviceServiceServicer
from interceptors import LoggingInterceptor, AuthInterceptor, RateLimitInterceptor

# Metrics
REQUEST_COUNT = Counter(
    'device_service_requests_total',
    'Total requests',
    ['method', 'status']
)
REQUEST_LATENCY = Histogram(
    'device_service_request_latency_seconds',
    'Request latency',
    ['method']
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


async def serve():
    # Start metrics server
    start_http_server(8001)

    # Create server with interceptors
    server = grpc.aio.server(
        futures.ThreadPoolExecutor(max_workers=10),
        interceptors=[
            LoggingInterceptor(),
            AuthInterceptor(),
            RateLimitInterceptor(rate=100, per_seconds=1),
        ],
        options=[
            ('grpc.max_send_message_length', 50 * 1024 * 1024),
            ('grpc.max_receive_message_length', 50 * 1024 * 1024),
            ('grpc.keepalive_time_ms', 10000),
            ('grpc.keepalive_timeout_ms', 5000),
            ('grpc.keepalive_permit_without_calls', True),
            ('grpc.http2.max_pings_without_data', 0),
            ('grpc.http2.min_time_between_pings_ms', 10000),
            ('grpc.http2.min_ping_interval_without_data_ms', 5000),
        ],
    )

    # Add services
    device_service_pb2_grpc.add_DeviceServiceServiceServicer_to_server(
        DeviceServiceServicer(), server
    )

    # Add health check service
    health_servicer = HealthServicer()
    health_pb2_grpc.add_HealthServicer_to_server(health_servicer, server)
    health_servicer.set(
        "device_service.DeviceServiceService",
        health_pb2.HealthCheckResponse.SERVING
    )

    # Add reflection for debugging
    SERVICE_NAMES = (
        device_service_pb2.DESCRIPTOR.services_by_name['DeviceServiceService'].full_name,
        reflection.SERVICE_NAME,
    )
    reflection.enable_server_reflection(SERVICE_NAMES, server)

    # Instrument with OpenTelemetry
    GrpcInstrumentorServer().instrument()

    # Start server
    listen_addr = '[::]:50051'
    server.add_insecure_port(listen_addr)
    logger.info(f"Starting gRPC server on {listen_addr}")

    await server.start()

    # Graceful shutdown
    async def graceful_shutdown():
        logger.info("Shutting down gracefully...")
        await server.stop(5)

    try:
        await server.wait_for_termination()
    except KeyboardInterrupt:
        await graceful_shutdown()


if __name__ == '__main__':
    asyncio.run(serve())
```

## device-service/service.py

```python
import uuid
from datetime import datetime
from typing import AsyncIterator
import grpc
import asyncio
from sqlalchemy.ext.asyncio import AsyncSession

from generated import device_service_pb2
from generated import device_service_pb2_grpc
from generated import common_pb2
from database import get_session
from models import DeviceModel
from events import publish_event


class DeviceServiceServicer(device_service_pb2_grpc.DeviceServiceServiceServicer):

    async def CreateDevice(
        self,
        request: device_service_pb2.CreateDeviceRequest,
        context: grpc.aio.ServicerContext,
    ) -> device_service_pb2.CreateDeviceResponse:
        async with get_session() as session:
            # Create entity
            device = DeviceModel(
                id=str(uuid.uuid4()),
                name=request.name,
                email=request.email,
                metadata=dict(request.metadata),
                status="active",
            )
            session.add(device)
            await session.commit()
            await session.refresh(device)

            # Publish event
            await publish_event(
                event_type="DeviceCreated",
                data={device.to_dict()},
            )

            return device_service_pb2.CreateDeviceResponse(
                device=self._to_proto(device)
            )

    async def GetDevice(
        self,
        request: device_service_pb2.GetDeviceRequest,
        context: grpc.aio.ServicerContext,
    ) -> device_service_pb2.GetDeviceResponse:
        async with get_session() as session:
            device = await session.get(DeviceModel, request.id)

            if not device:
                context.set_code(grpc.StatusCode.NOT_FOUND)
                context.set_details(f"Device not found: {request.id}")
                return device_service_pb2.GetDeviceResponse()

            return device_service_pb2.GetDeviceResponse(
                device=self._to_proto(device)
            )

    async def ListDevices(
        self,
        request: device_service_pb2.ListDevicesRequest,
        context: grpc.aio.ServicerContext,
    ) -> device_service_pb2.ListDevicesResponse:
        async with get_session() as session:
            page = request.pagination.page or 1
            page_size = request.pagination.page_size or 20

            # Query with filters
            query = session.query(DeviceModel)

            if request.status:
                query = query.filter(DeviceModel.status == request.status)

            if request.search:
                query = query.filter(
                    DeviceModel.name.ilike(f"%{request.search}%")
                )

            # Count total
            total = await session.execute(query.count())

            # Paginate
            devices = await session.execute(
                query.offset((page - 1) * page_size).limit(page_size)
            )

            return device_service_pb2.ListDevicesResponse(
                devices=[self._to_proto(u) for u in devices.scalars()],
                pagination=common_pb2.PaginationResponse(
                    total=total,
                    page=page,
                    page_size=page_size,
                    total_pages=(total + page_size - 1) // page_size,
                ),
            )

    async def WatchDevices(
        self,
        request: common_pb2.Empty,
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[device_service_pb2.DeviceEvent]:
        """Server streaming - watch for device changes"""
        # Subscribe to Redis pub/sub or message queue
        from events import subscribe_events

        async for event in subscribe_events("Device*"):
            if context.cancelled():
                break

            yield device_service_pb2.DeviceEvent(
                event_type=event["type"],
                device=self._to_proto(event["data"]),
                timestamp=common_pb2.Timestamp(
                    seconds=int(datetime.now().timestamp())
                ),
            )

    async def BulkDeviceOperations(
        self,
        request_iterator: AsyncIterator[device_service_pb2.CreateDeviceRequest],
        context: grpc.aio.ServicerContext,
    ) -> AsyncIterator[device_service_pb2.CreateDeviceResponse]:
        """Bidirectional streaming - bulk create devices"""
        async for request in request_iterator:
            response = await self.CreateDevice(request, context)
            yield response

    def _to_proto(self, model: DeviceModel) -> device_service_pb2.Device:
        return device_service_pb2.Device(
            id=model.id,
            name=model.name,
            email=model.email,
            status=model.status,
            metadata=model.metadata or {},
            created_at=common_pb2.Timestamp(
                seconds=int(model.created_at.timestamp())
            ),
            updated_at=common_pb2.Timestamp(
                seconds=int(model.updated_at.timestamp())
            ) if model.updated_at else None,
        )
```

## device-service/client.py (gRPC Client)

```python
import grpc
from grpc import aio
import asyncio
from typing import List, AsyncIterator

from generated import device_service_pb2
from generated import device_service_pb2_grpc
from generated import common_pb2


class DeviceServiceClient:
    def __init__(self, host: str = "localhost", port: int = 50051):
        self.channel = None
        self.stub = None
        self.host = host
        self.port = port

    async def connect(self):
        self.channel = aio.insecure_channel(
            f"{self.host}:{self.port}",
            options=[
                ('grpc.keepalive_time_ms', 10000),
                ('grpc.keepalive_timeout_ms', 5000),
            ],
        )
        self.stub = device_service_pb2_grpc.DeviceServiceServiceStub(self.channel)

    async def close(self):
        if self.channel:
            await self.channel.close()

    async def create_device(
        self,
        name: str,
        email: str,
        metadata: dict = None,
    ) -> device_service_pb2.Device:
        request = device_service_pb2.CreateDeviceRequest(
            name=name,
            email=email,
            metadata=metadata or {},
        )
        response = await self.stub.CreateDevice(request)
        return response.device

    async def get_device(self, id: str) -> device_service_pb2.Device:
        request = device_service_pb2.GetDeviceRequest(id=id)
        response = await self.stub.GetDevice(request)
        return response.device

    async def list_devices(
        self,
        page: int = 1,
        page_size: int = 20,
        status: str = None,
        search: str = None,
    ) -> List[device_service_pb2.Device]:
        request = device_service_pb2.ListDevicesRequest(
            pagination=common_pb2.PaginationRequest(
                page=page,
                page_size=page_size,
            ),
            status=status or "",
            search=search or "",
        )
        response = await self.stub.ListDevices(request)
        return list(response.devices)

    async def watch_devices(self) -> AsyncIterator[device_service_pb2.DeviceEvent]:
        request = common_pb2.Empty()
        async for event in self.stub.WatchDevices(request):
            yield event

    async def bulk_create_devices(
        self,
        items: List[dict],
    ) -> List[device_service_pb2.Device]:
        async def request_generator():
            for item in items:
                yield device_service_pb2.CreateDeviceRequest(
                    name=item["name"],
                    email=item["email"],
                    metadata=item.get("metadata", {}),
                )

        results = []
        async for response in self.stub.BulkDeviceOperations(request_generator()):
            results.append(response.device)
        return results


# Usage example
async def main():
    client = DeviceServiceClient()
    await client.connect()

    try:
        # Create
        device = await client.create_device(
            name="John Doe",
            email="john@example.com",
        )
        print(f"Created: {device.id}")

        # Get
        device = await client.get_device(device.id)
        print(f"Got: {device.name}")

        # List
        devices = await client.list_devices(page=1, page_size=10)
        print(f"Total: {len(devices)}")

        # Watch (streaming)
        async for event in client.watch_devices():
            print(f"Event: {event.event_type} - {event.device.id}")
            break  # Stop after first event

    finally:
        await client.close()


if __name__ == "__main__":
    asyncio.run(main())
```

## docker-compose.yml

```yaml
version: '3.8'

services:
  device-service:
    build: ./device-service
    ports:
      - "50051:50051"
      - "8001:8001"  # Metrics
    environment:
      - DATABASE_URL=postgresql://admin:password@postgres:5432/device_service_db
      - RABBITMQ_URL=amqp://admin:password@rabbitmq:5672
    depends_on:
      - postgres
      - rabbitmq
    networks:
      - grpc-network

  telemetry-service:
    build: ./telemetry-service
    ports:
      - "50052:50051"
    environment:
      - DATABASE_URL=postgresql://admin:password@postgres:5432/telemetry_service_db
      - DEVICE_SERVICE_GRPC_HOST=device-service
      - DEVICE_SERVICE_GRPC_PORT=50051
    depends_on:
      - device-service
    networks:
      - grpc-network

  postgres:
    image: postgres:15
    environment:
      POSTGRES_USER: admin
      POSTGRES_PASSWORD: password
    volumes:
      - postgres_data:/var/lib/postgresql/data
    networks:
      - grpc-network

  rabbitmq:
    image: rabbitmq:3-management
    ports:
      - "15672:15672"
    networks:
      - grpc-network

networks:
  grpc-network:
    driver: bridge

volumes:
  postgres_data:
```

This gRPC microservices setup includes:
- **Protocol Buffers** definitions with common types
- **Unary RPCs** for CRUD operations
- **Server streaming** for real-time updates
- **Bidirectional streaming** for bulk operations
- **Health checks** and **reflection** for debugging
- **Interceptors** for logging, auth, and rate limiting
- **OpenTelemetry** instrumentation
- **Prometheus** metrics
- **Async Python** implementation with SQLAlchemy
